<?php
declare(strict_types=1);
define('XAR_SPECIAL_FIXTURE_ONLY',true);
require __DIR__.'/tactical-special-effects.php';
$specialChecks=0;
$id='ability-9d9973fa-0555-4807-bbd6-af6f1adf640d';
$db=specialFixture();$character=$db->payload('character:character-player');
$character['abilities']=[['id'=>$id,'name'=>'Lancer fulgurant','effect'=>'movement','formula'=>'0','manaCost'=>0,'fatigueCost'=>10,'cooldownRounds'=>5,'usesPerRest'=>1,'restRecharge'=>'long','castingStatId'=>'character-stat-agility']];
$character['stats']=['force'=>0,'agility'=>0,'intelligence'=>0,'spiritSocial'=>0];$db->put('character:character-player',$character);
$items=['version'=>1,'templates'=>[['id'=>'healing-potion','name'=>'Potion de recette','kind'=>'object','active'=>['version'=>1,'useLabel'=>'Boire','authority'=>'owner','effects'=>[['kind'=>'heal-max-die','percent'=>30]]]]],'instances'=>[]];
foreach(['first-vial','second-vial'] as $vial)$items['instances'][]=['id'=>$vial,'templateId'=>'healing-potion','revision'=>1,'location'=>['kind'=>'inventory','characterId'=>'character-player']];
$db->put('items',$items);
$ability=normalizeOnlineAbilities($character['abilities'])[0];
specialCheck(($ability['manualAction']??false)===true&&$ability['castingStatId']==='','Preset manual with no casting roll');
specialCheck($ability['fatigueCost']===6&&$ability['cooldownRounds']===3&&$ability['usesPerRest']===2&&$ability['restRecharge']==='short','New common costs and limits');
specialCheck(validApplicationAbilityCastingFields(['manualAction'=>true])&&!validApplicationAbilityCastingFields(['manualAction'=>'true']),'Manual metadata type checked');
$normalized=normalizeOnlineAbilities([[...$ability,'manualAction'=>false,'fatigueCost'=>7]])[0];specialCheck($normalized['manualAction']===false&&$normalized['fatigueCost']===7,'Explicit later settings preserved');
$beforeCharacter=$db->payload('character:character-player');$beforeMonster=$db->payload('token:scene-one:token-monster');$beforeSource=$db->payload('token:scene-one:token-player');$beforeActivity=$db->payload('activity');
$requestId='manual-potions-replay-'.randomToken(16);$args=['requestId'=>$requestId];
$first=specialUse($db,$id,'token-player',$args);specialCheck($first->status===200,'Native manual activation: '.json_encode($first->body));
specialCheck(($first->body['cast']['success']??false)===true&&empty($first->body['castRoll'])&&empty($first->body['pendingValidation']),'No cast check or critical validation at zero stat');
specialCheck($db->payload('character:character-player')['fatigue']['current']===6,'Fatigue paid once');
$again=specialUse($db,$id,'token-player',$args);specialCheck($again->status===200&&!empty($again->body['deduplicated']),'Native replay deduplicates');
specialCheck($db->payload('character:character-player')['fatigue']['current']===6,'Replay spends no extra fatigue');
$timer=array_values(array_filter($db->payload('activity')['actionTimers'],fn($timer)=>($timer['abilityId']??'')===$id))[0];specialCheck($timer['restUseCount']===1&&$timer['readyRound']===4,'Three rounds and one activation recorded');
specialCheck(specialUse($db,$id,'token-player')->status===409,'Use refused during cooldown');
$initiative=$db->payload('initiative:scene-one');$initiative['round']=4;$initiative['turnSerial']++;$db->put('initiative:scene-one',$initiative);
specialCheck(specialUse($db,$id,'token-player')->status===200,'Second use after three rounds');
$initiative['round']=7;$initiative['turnSerial']++;$db->put('initiative:scene-one',$initiative);
specialCheck(specialUse($db,$id,'token-player')->status===409,'Third use refused after cooldown by short rest quota');
specialCheck($db->payload('character:character-player')['fatigue']['current']===12,'Only two real activations paid');
specialCheck($db->payload('items')===$items,'Both potions stay in inventory with unchanged revision');
specialCheck($db->payload('character:character-player')['resources']===$beforeCharacter['resources'],'Source HP and mana unchanged');
specialCheck($db->payload('token:scene-one:token-monster')===$beforeMonster,'Other unit unchanged');
$source=$db->payload('token:scene-one:token-player');foreach(['x','y','hp','mana'] as $field)specialCheck(isset($source[$field],$beforeSource[$field])&&(float)$source[$field]===(float)$beforeSource[$field],'No source movement/resource mutation: '.$field);
$activity=$db->payload('activity');specialCheck(count($activity['rolls']??[])===count($beforeActivity['rolls']??[]),'No dice rolled');
foreach(['pendingAbilityCasts','abilityExecutions','attackEnhancements','damageOverTime'] as $field)specialCheck(empty($activity[$field]),'No automatic potion/workflow effect: '.$field);
fwrite(STDOUT,json_encode(['ok'=>true,'checks'=>$specialChecks],JSON_UNESCAPED_UNICODE)."\n");
